(6483902, 964270, 15711, '<td valign="top">HA HA Great title. :) People either LOVE coffee or hate it.  I''m of the first persuasion as I sit here with mug #1.  I like this. 7</td>', 'HA HA Great title. :) People either LOVE coffee or hate it.  I''m of the first persuasion as I sit here with mug #1.  I like this. 7', '2011-07-29 10:27:54.000000', NULL, 1),
(6483903, 964216, 15711, '<td valign="top">YUM!!! I like the tilt and the way the basil sprig ties in to the place mat''s color.</td>', 'YUM!!! I like the tilt and the way the basil sprig ties in to the place mat''s color.', '2011-07-29 10:28:43.000000', NULL, 1),
